import { useEffect, useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { toast } from 'sonner';
import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import PlusIcon from '@/components/icons/popups/PlusIcon';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import {
    AddDepartmentDialogFormValues,
    AddDepartmentDialogSchema,
    NONE_HEAD,
    addDepartmentDialogDefaultValues,
} from './add-department-dialog-schema';
import { Textarea } from '@/components/ui/textarea';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { headIdForApi } from '../../forms/schemas/addDepartment/add-department-schema';

interface AddDepartmentDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSaved?: () => void;
}

export default function AddDepartmentDialog({ open, onOpenChange, onSaved }: AddDepartmentDialogProps) {
    const [saving, setSaving] = useState(false);
    const [employeeOptions, setEmployeeOptions] = useState<{ name: string; value: string }[]>([
        { name: '— بدون —', value: NONE_HEAD },
    ]);

    const form = useForm<AddDepartmentDialogFormValues>({
        resolver: zodResolver(AddDepartmentDialogSchema),
        defaultValues: addDepartmentDialogDefaultValues,
    });

    useEffect(() => {
        if (open) {
            form.reset(addDepartmentDialogDefaultValues);
        }
    }, [open, form]);

    useEffect(() => {
        if (!open) return;
        const load = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.employee.simpleList });
                const rows = res.data?.data;
                const list = Array.isArray(rows)
                    ? rows.map((e: { id: number; name: string }) => ({
                          name: e.name ?? `موظف #${e.id}`,
                          value: String(e.id),
                      }))
                    : [];
                setEmployeeOptions([{ name: '— بدون —', value: NONE_HEAD }, ...list]);
            } catch {
                setEmployeeOptions([{ name: '— بدون —', value: NONE_HEAD }]);
            }
        };
        void load();
    }, [open]);

    const onSubmit = async (data: AddDepartmentDialogFormValues) => {
        setSaving(true);
        try {
            await apiPost({
                endpoint: endpoints.departments.create,
                body: {
                    name: data.name.trim(),
                    description: data.description?.trim() ? data.description.trim() : null,
                    department_head_id: headIdForApi(data.department_head_id),
                    max_employees: data.max_employees,
                },
            });
            toast.success('تم حفظ القسم بنجاح', { className: 'font-cairo' });
            onSaved?.();
            onOpenChange(false);
        } catch (e: unknown) {
            const err = e as { response?: { data?: { msg?: string } } };
            toast.error(err.response?.data?.msg || 'تعذر حفظ القسم', { className: 'font-cairo' });
        } finally {
            setSaving(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent
                showCloseButton={false}
                dir="rtl"
                className="max-w-[640px] max-h-[92vh] overflow-y-auto rounded-lg p-6 sm:p-8 bg-white-blue-50 font-cairo gap-0 border-[#E8E7EA]"
            >
                <DialogHeader className="flex flex-col items-stretch space-y-0">
                    <div className="flex flex-row items-center gap-2 mb-4">
                        <PlusIcon />
                        <h2 className="text-[22px] font-bold text-primery-blue-500">إضافة قسم</h2>
                    </div>
                    <div className="w-full border-b border-[#D1D1D1]" />
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6 space-y-6">
                        <div className="space-y-5">
                            <FormField
                                control={form.control}
                                name="name"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            اسم القسم
                                        </FormLabel>
                                        <FormControl>
                                            <Input
                                                {...field}
                                                type="text"
                                                placeholder="ادخل اسم القسم"
                                                className="placeholder:text-white-blue-600"
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                            <FormField
                                control={form.control}
                                name="description"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            وصف القسم
                                        </FormLabel>
                                        <FormControl>
                                            <Textarea
                                                {...field}
                                                placeholder="وصف اختياري..."
                                                rows={4}
                                                className="placeholder:text-white-blue-600"
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                            <FormField
                                control={form.control}
                                name="department_head_id"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            مسؤول القسم
                                        </FormLabel>
                                        <Select onValueChange={field.onChange} value={field.value ?? NONE_HEAD}>
                                            <FormControl>
                                                <SelectTrigger>
                                                    <SelectValue placeholder="اختر موظفاً" />
                                                </SelectTrigger>
                                            </FormControl>
                                            <SelectContent>
                                                {employeeOptions.map((o) => (
                                                    <SelectItem key={o.value} value={o.value} className="font-cairo">
                                                        {o.name}
                                                    </SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                            <FormField
                                control={form.control}
                                name="max_employees"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            الحد الأقصى لعدد الموظفين
                                        </FormLabel>
                                        <FormControl>
                                            <Input
                                                {...field}
                                                type="number"
                                                min={1}
                                                className="placeholder:text-white-blue-600"
                                                dir="ltr"
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                            <div className="space-y-1">
                                <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                    العدد الحالي للموظفين
                                </FormLabel>
                                <Input readOnly value="0" className="bg-[#F3F4F6] text-[#4B5563]" dir="ltr" />
                                <p className="text-[11px] text-[#90868C]">يُحدَّث تلقائياً لاحقاً</p>
                            </div>
                        </div>

                        <div className="flex flex-row-reverse gap-4 pt-2">
                            <PrimaryButton type="submit" disabled={saving} className="flex-1 text-base font-semibold py-3">
                                {saving ? 'جاري الحفظ...' : 'إضافة'}
                            </PrimaryButton>
                            <SecondaryButton
                                type="button"
                                className="flex-1 text-base font-semibold py-3"
                                onClick={() => onOpenChange(false)}
                            >
                                إلغاء
                            </SecondaryButton>
                        </div>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}
